// Pixabay image found — pass URL through as JSON (no binary yet)
// Binary download happens after Merge to avoid binary data being stripped
return [{ json: { imageUrl: $json.imageUrl, source: 'pixabay' } }];

const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
const response = $input.item.json;

let imageUrl = null;

if (response && response.hits && response.hits.length > 0) {
  const hit = response.hits.find(function(h) { return h.largeImageURL || h.webformatURL; });
  if (hit) {
    imageUrl = hit.largeImageURL || hit.webformatURL;
  }
}

return [{ json: { chatId: chatId, imageUrl: imageUrl, hasPixabay: !!imageUrl } }];

const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){}try{return $('Scheduled Config').first().json.chatId}catch(e){}return $getWorkflowStaticData('global')['currentChatId']})();
const staticData = $getWorkflowStaticData('global');
const article = staticData['article_' + chatId];

// Read publish intent from Detect Stage
const isPublish = $('Detect Stage').item.json.isPublish || false;

if (!article) {
  return [{ json: {
    chatId: chatId, error: true,
    errorMsg: '⚠️ *No article found*\n\nDraft an article first, then reply *post to WordPress* or *publish to WordPress*.'
  }}];
}

return [{ json: {
  chatId: chatId, error: false,
  title: article.title || 'Untitled Article',
  content: article.content || '',
  slug: article.slug || '',
  excerpt: article.excerpt || '',
  tags: article.tags || '',
  category: article.category || 'uncategorized',
  wpMediaId: article.wpMediaId || 0,
  isPublish: isPublish
}}];

