const parseTopics = (brief) => {
  const text = String(brief || '');
  const header = /^[ \t>#*_]*TOPIC\s+\d+\b[^\n]*$/gim;
  const marks = [];
  let m;
  while ((m = header.exec(text)) !== null) marks.push({ start: m.index, end: header.lastIndex });
  const topics = [];
  for (let i = 0; i < marks.length; i++) {
    const body = text.slice(marks[i].end, i + 1 < marks.length ? marks[i + 1].start : text.length).trim();
    const t = body.match(/^[ \t>*_-]*Title[*_]*\s*:[*_]*\s*(.+)$/im);
    const title = t ? t[1].replace(/[*_]+/g, '').trim() : '';
    // A slice with no title or too short to be a dossier is malformed - drop it rather than hand
    // the writer something it will fill with invention.
    if (title && body.length >= 80) topics.push({ title, body });
  }
  return topics.slice(0, 5);
};

